CREATE TABLE product(id BIGINT PRIMARY KEY,name VARCHAR(255) NOT NULL,description VARCHAR(255),category VARCHAR(40) NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>0),available BOOLEAN NOT NULL);
CREATE TABLE dining_table(id INTEGER PRIMARY KEY,token VARCHAR(255) NOT NULL UNIQUE,active BOOLEAN NOT NULL);
CREATE TABLE customer_order(id UUID PRIMARY KEY,version BIGINT NOT NULL,request_key UUID NOT NULL UNIQUE,access_token VARCHAR(255) NOT NULL,table_number INTEGER REFERENCES dining_table(id),status VARCHAR(40) NOT NULL,total NUMERIC(12,2) NOT NULL CHECK(total>0),notes VARCHAR(500),created_at TIMESTAMP WITH TIME ZONE,paid_at TIMESTAMP WITH TIME ZONE,payment_id VARCHAR(255) UNIQUE,checkout_url VARCHAR(2000));
CREATE TABLE order_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id UUID REFERENCES customer_order(id),product_id BIGINT REFERENCES product(id),name VARCHAR(255) NOT NULL,unit_price NUMERIC(12,2) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20));
CREATE INDEX idx_order_status_created ON customer_order(status,created_at);
